import { createPortal } from "react-dom";
import { cx } from "../../lib/cx";
import { date, dateTime, money, number } from "../../lib/format";
import { SystemNote } from "../ui/KeyFigures";

// A report as a document - the same layout on screen, on paper and in the
// PDF from the server:
//
//   Keiyian Farmers Cooperative Society Ltd
//   Nuru ya Jamii
//   Sales report - November 2026
//   Generated by <name> on 08 Nov 2026, 21:24 EAT
//
// then a Summary table and one ruled table (rows and columns) per section.

const NUMERIC = ["money", "number", "percent"];
const SIGN_OFF = ["Prepared by", "Checked by", "Confirmed by"];

const amount = (value) => Number(value).toLocaleString("en-KE", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const cell = (value, type) => {
  if (value === "" || value == null) return "";
  if (type === "percent") return `${number(value)}%`;
  if (type === "money") return amount(value);
  if (type === "number") return number(value);
  if (type === "date") return date(value);
  return value;
};
const alignRight = (column) => column.align === "right" || NUMERIC.includes(column.type);
// Shortfalls and falls read in red, as on a paper report.
const isNegative = (value, column) => alignRight(column) && (typeof value === "number" ? value < 0 : /^(KES )?-\d/.test(String(value ?? "")));

const summaryText = (item) => {
  if (item.type === "money") return money(item.value);
  if (item.type === "percent") return `${number(item.value)}%`;
  if (item.type === "text") return item.value;
  return number(item.value);
};

/** One table of a report: a title, column headings, rows and an optional totals row. */
export const ReportTable = ({ section, emptyText = "No records for this period.", narrow = false }) => {
  // Wide tables (the cane status sheet has 12 columns) get tighter cells.
  const pad = section.columns.length > 8 ? "px-2 py-1.5" : "px-3 py-1.5";
  return (
    <section className="report-table">
      <h3 className="mb-1.5 text-sm font-semibold text-primary-800">{section.title}</h3>
      <div className={cx("scrollbar-thin overflow-x-auto", narrow && "report-narrow max-w-xl")}>
        <table className="w-full border-collapse text-[13px] leading-snug">
          <thead>
            <tr className="bg-slate-100">
              {section.columns.map((c) => (
                <th key={c.key} scope="col" className={cx("border border-slate-300 align-bottom text-xs font-semibold text-slate-700", pad, alignRight(c) ? "text-right" : "text-left")}>{c.label}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {section.rows.length === 0 ? (
              <tr><td colSpan={section.columns.length} className={cx("border border-slate-300 italic text-slate-400", pad)}>{emptyText}</td></tr>
            ) : section.rows.map((row, i) => (
              <tr key={i} className="hover:bg-slate-50">
                {section.columns.map((c) => (
                  <td
                    key={c.key}
                    className={cx(
                      "border border-slate-300 align-top",
                      pad,
                      alignRight(c) && "whitespace-nowrap text-right tabular-nums",
                      (c.weight ?? 0) >= 2 && "report-wide-cell",
                      isNegative(row[c.key], c) ? "text-rose-700" : "text-slate-800",
                    )}
                  >
                    {cell(row[c.key], c.type)}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
          {section.totals && (
            <tfoot>
              <tr className="bg-slate-100 font-semibold text-slate-900">
                {section.columns.map((c, i) => {
                  const value = section.totals[c.key];
                  return (
                    <td key={c.key} className={cx("border border-slate-300", pad, alignRight(c) && "whitespace-nowrap text-right tabular-nums", isNegative(value, c) && "text-rose-700")}>
                      {i === 0 ? section.totalLabel || "Total" : value != null ? cell(value, c.type) : ""}
                    </td>
                  );
                })}
              </tr>
            </tfoot>
          )}
        </table>
      </div>
    </section>
  );
};

/** Sign-off lines, as on the cooperative's paper reports. Printed only. */
const SignOff = () => (
  <div className="hidden space-y-6 pt-6 text-sm text-slate-900 print:block">
    {SIGN_OFF.map((role) => (
      <div key={role} className="flex items-end gap-2">
        <span className="w-28 shrink-0">{role}:</span>
        <span className="h-4 flex-1 border-b border-slate-500" />
        <span className="shrink-0 pl-4">Signature:</span>
        <span className="h-4 w-44 border-b border-slate-500" />
        <span className="shrink-0 pl-4">Date:</span>
        <span className="h-4 w-32 border-b border-slate-500" />
      </div>
    ))}
  </div>
);

/**
 * meta: { organisation, motto, generatedBy, generatedAt } from the report API.
 * report: { heading, summary, sections }.
 */
export const ReportDocument = ({ report, meta, emptyText }) => (
  <article className="report-document overflow-hidden rounded-xl border border-slate-200 bg-white shadow-card">
    <header className="report-header border-b-2 border-primary-800 px-6 pb-4 pt-6 text-center">
      <p className="text-lg font-bold tracking-tight text-primary-800">{meta.organisation}</p>
      {meta.motto && <p className="text-sm italic text-slate-500">{meta.motto}</p>}
      <h2 className="mt-3 text-base font-bold text-slate-900">{report.heading}</h2>
      <p className="mt-0.5 text-xs text-slate-500">Generated by {meta.generatedBy} on {dateTime(meta.generatedAt)} EAT</p>
    </header>
    <div className="space-y-6 px-6 py-6">
      <ReportTable
        narrow
        section={{
          title: "Summary",
          columns: [{ key: "item", label: "Item" }, { key: "value", label: "Value", align: "right" }],
          rows: report.summary.map((item) => ({ item: item.label, value: summaryText(item) })),
        }}
      />
      {report.sections.map((section) => <ReportTable key={section.title} section={section} emptyText={emptyText} />)}
      <SignOff />
    </div>
    <footer className="border-t border-slate-200 bg-slate-50/70 px-6 py-3">
      <SystemNote generatedAt={meta.generatedAt} />
    </footer>
  </article>
);

/**
 * What goes to the printer: only the report documents, each starting on a
 * new page - never the rest of the screen. Rendered outside the app root
 * and shown only when printing (see index.css).
 */
export const PrintArea = ({ children }) => createPortal(<div className="print-root">{children}</div>, document.body);
